#!/usr/bin/env python3
"""Build the bounded 2022 source-only RESTORED temperature proposal from frozen evidence."""
import csv, json, datetime, hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'proposals/restored_source_only_2022_august_outtemp'
src=json.loads((ROOT/'data/b5_2022_2023_eu_old_gap_source_rows.json').read_text())['rows']
# The 2022 August 27 episode is the only 2022 source-row interval with strong
# local-reference agreement; exclude the one row whose source outTemp is NULL.
rows=[r for r in src if datetime.datetime.fromtimestamp(r['dateTime'],datetime.timezone.utc).year==2022 and r['outTemp'] is not None]
assert len(rows)==65 and all(r['usUnits']==16 and r['interval']==5 for r in rows)
reason=('RESTORED; MODERATE provenance: exact 5-minute outTemp row in owner-attested known historical archive pocasi-loucka.eu_old; '
        'this merged archive is not an independently proven original sensor export, and prior intentional cleaning cannot be excluded. '
        'Exact timestamp/unit, source continuity, reconstruction absence, zero change events, physical range and local LuhaMet context checked; outTemp only.')
ops=[]; meta=[]; presence=[]
for r in rows:
    ts=int(r['dateTime']); utc=datetime.datetime.fromtimestamp(ts,datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    v=float(r['outTemp'])
    ops.append({'operation':'insert','timestamp':ts,'variable':'outTemp','new_value':v,'expected_old_value':None,'source_database':'pocasi-loucka.eu_old','source_time':ts,'source_value':v,'reason':reason,'us_units':16,'interval_minutes':5})
    evid={k:r.get(k) for k in ['outTemp','outHumidity','rain','rainRate','windSpeed','windGust','windDir','barometer','pressure','altimeter']}
    meta.append({'timestamp':ts,'utc':utc,'classification':'RESTORED','operation':'insert outTemp only','confidence':'MODERATE','source_lineage':'OWNER_ATTESTED known historical archive; exact original origin and sensor export unknown; older cleaning and merge cannot be excluded.','uncertainty':'Historical-measurement restoration, not a statistical estimate; MODERATE source provenance. No individual prediction interval applies.','source_evidence':{'archive':'pocasi-loucka.eu_old','source_unit':16,'source_interval_minutes':5,'source_values':evid,'target_row_exists_in_reconstruction':False,'reconstruction_change_events':int(r.get('change_event_count',0)),'archive_row_presence_by_database':{'loucka_reconstruction':False,'pocasi-loucka.eu':False,'pocasi-loucka.eu_GW1000':False,'pocasi-loucka.eu_old':True,'old_weewx':False,'weewx_WH1080':False},'quality_checks':{'five_minute_grid':ts%300==0,'outTemp_nonnull':True,'outTemp_zero':v==0,'physical_temperature_range_c':-50<=v<=60,'source_row_dynamic':True,'local_reference_review':'2022-08-27 exact-time LuhaMet; 65 paired temperatures; bias +0.058 C, MAE 0.303 C, p95 abs 0.756 C, max abs 1.125 C; inter-station difference is contextual, not a guarantee.'}},'review_decision':'Include in bounded pilot: exact aligned source row, source interval and unit consistent across cohort, no target or change event, dynamically varying physically plausible series, and close exact-time LuhaMet agreement. Owner-attested history warns cleaning is possible, so provenance remains MODERATE. Other fields are not proposed.'})
# CSV
with (OUT/'corrections.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(ops[0]));w.writeheader();w.writerows(ops)
(OUT/'corrections.json').write_text(json.dumps(ops,indent=2)+'\n')
(OUT/'candidate_metadata.json').write_text(json.dumps(meta,indent=2)+'\n')
# Availability explicitly documents all six archives; other five exact-key queries were empty for the episode.
pa=[]
for x in meta:
 pa.append({'timestamp':x['timestamp'],'utc':x['utc'],**x['source_evidence']['archive_row_presence_by_database'],'source_values':x['source_evidence']['source_values'],'change_events':x['source_evidence']['reconstruction_change_events']})
(OUT/'per_target_archive_presence.json').write_text(json.dumps({'schema':'per-target-six-archive-presence-v1','episode':'2022-08-27 04:05–09:40 UTC; source rows lie within open target gap','targets':pa},indent=2)+'\n')
with (OUT/'per_target_archive_presence.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=['timestamp','utc','loucka_reconstruction','pocasi-loucka.eu','pocasi-loucka.eu_GW1000','pocasi-loucka.eu_old','old_weewx','weewx_WH1080','change_events']);w.writeheader()
 for x in pa: w.writerow({k:x.get(k) for k in w.fieldnames})
batches=[]
for i in range(0,len(ops),50): batches.append({'batch_id':f'restored-2022-august-outtemp-{i//50+1:02d}-v1','size':len(ops[i:i+50]),'operations':ops[i:i+50],'database_write_or_staging':False})
(OUT/'weather_mcp_batches.json').write_text(json.dumps({'contract':'Weather MCP proposal format; not submitted','max_batch_size':50,'batch_count':len(batches),'batches':batches},indent=2)+'\n')
(OUT/'source_metadata.json').write_text(json.dumps({'source_archive':'pocasi-loucka.eu_old','owner_statement':'OWNER_ATTESTED: known historical archive; exact original origin and cleaning/merge rules unknown','source_unit':16,'interval_minutes':5,'rows_in_episode':66,'nonnull_outTemp':65,'proposed_outTemp':65,'excluded_null_outTemp':1,'other_archive_rows_in_episode':0,'target_rows_in_reconstruction':0,'change_events':0,'source_context':'Frozen read-only source snapshot; source archive values already represented in field units; no conversion applied in package.'},indent=2)+'\n')
(OUT/'offline_simulation.json').write_text(json.dumps({'simulation':'local in-memory proposal accounting only','operations':65,'physical_insert_rows':65,'updates':0,'target_rows_created_in_memory':65,'other_variables_synthesized':0,'database_access':'NONE','database_writes':0,'staging':False,'application':'NOT_APPLIED'},indent=2)+'\n')
(OUT/'dependency_metadata.json').write_text(json.dumps({'dependency_order':'No downstream updates in this package; all operations are independent inserts.','batch_limit':50,'batch_count':2,'batch_sizes':[50,15],'episode_split_due_to_batch_limit':True,'recheck_target_state_before_any_future_approved_application':True,'never_synthesize_other_variables':True},indent=2)+'\n')
(OUT/'excluded_cases.csv').write_text('timestamp,utc,field,disposition,reason\n1661591400,2022-08-27T09:10:00Z,outTemp,REVIEW_REQUIRED_SOURCE_NULL,"Source row exists but outTemp is NULL; no temperature proposal"\n')
(OUT/'field_exclusions.csv').write_text('field,source_nonnull,disposition,reason\noutHumidity,66,NOT_PROPOSED,"No independent RH provenance/validation in this temperature package"\nrain,66,NOT_PROPOSED,"Gauge/counter semantics unresolved; do not synthesize or restore"\nrainRate,66,NOT_PROPOSED,"Gauge/driver semantics unresolved; do not synthesize or restore"\nwindSpeed,66,NOT_PROPOSED,"Historical wind transformations unresolved"\nwindGust,66,NOT_PROPOSED,"Historical wind transformations unresolved"\nwindDir,0,NOT_AVAILABLE,"Source is NULL throughout this episode"\nbarometer,66,NOT_PROPOSED,"Field-specific source provenance/validation not performed"\npressure,66,NOT_PROPOSED,"Derived/secondary field not part of this restoration"\naltimeter,66,NOT_PROPOSED,"Derived/secondary field not part of this restoration"\n')
(OUT/'README.md').write_text('''# 2022-08-27 source-only temperature restoration pilot\n\n**RESTORED / MODERATE; 65 outTemp inserts, not approved, not submitted, not applied.**\n\nThe source is `pocasi-loucka.eu_old` at timestamps 2022-08-27 04:10–09:35 UTC. All 66 source rows are on the 300-second grid, `usUnits=16`, `interval=5`; 65 have non-NULL outTemp, one is excluded. Exact-key episode queries found no rows in reconstruction, pocasi-loucka.eu, GW1000, old_weewx or WH1080. Reconstruction target rows and change events are absent.\n\nThe source temperatures vary continuously (16.944–22.025 °C) with no zero/plateau flag. At 65 exact LuhaMet pairs, bias is +0.058 °C, MAE 0.303 °C, p95 absolute difference 0.756 °C, maximum 1.125 °C. This supports plausibility but does not certify individual correctness. Owner-attested archive history includes merges and past cleaning; exact original source identity and intent of omission are unknown. The package therefore has MODERATE provenance and is a bounded candidate, not an automatic restoration.\n\nOnly outTemp is proposed. Rain, rainRate and wind fields remain excluded; no zeros or other variables are synthesized. Each insert creates a new archive row with required timestamp/unit/interval and outTemp, while all other values remain NULL. Batch size is at most 50.\n\nReproduce locally with `python3 validate.py` and `python3 simulate.py`. These scripts use only packaged local data/evidence.\n''')
(OUT/'PRE_APPLICATION_CHECKLIST.md').write_text('''# Pre-application checklist — 2022-08-27 outTemp pilot\n\nStatus: NOT_APPROVED / actual Weather MCP dry-run NOT_RUN / NOT_APPLIED.\n\nBefore any separately approved action: verify fresh backup and tested rollback; re-read target rows and all six source archives read-only; confirm 65 absent targets and the one excluded NULL source row; inspect current reconstruction_changes; confirm no concurrent corrections or protected-period collision; review per-target `RESTORED`/`MODERATE` reasons; confirm Weather MCP contract and batch limit (50); apply only after explicit approval; verify each row and NULL state of all non-proposed variables; compare archive integrity and audit history; rollback only using the approved transaction/restore plan. This package does not execute these steps or stage anything.\n''')
# validator and simulator are local only; build manifest last.
(OUT/'simulate.py').write_text('''#!/usr/bin/env python3\nimport json\nfrom pathlib import Path\nr=Path(__file__).resolve().parent; ops=json.loads((r/'corrections.json').read_text())\nsim={'simulation':'local in-memory accounting only','operations':len(ops),'physical_insert_rows':sum(o['operation']=='insert' for o in ops),'updates':sum(o['operation']=='update' for o in ops),'other_variables_synthesized':0,'database_access':'NONE','database_writes':0,'staging':False,'application':'NOT_APPLIED'}\nprint(json.dumps(sim,indent=2))\n''')
(OUT/'validate.py').write_text('''#!/usr/bin/env python3\nimport json,hashlib,datetime,csv\nfrom pathlib import Path\nr=Path(__file__).resolve().parent\nops=json.loads((r/'corrections.json').read_text()); meta=json.loads((r/'candidate_metadata.json').read_text()); pres=json.loads((r/'per_target_archive_presence.json').read_text()); batches=json.loads((r/'weather_mcp_batches.json').read_text()); man=json.loads((r/'manifest.json').read_text())\nassert len(ops)==len(meta)==65 and len({o['timestamp'] for o in ops})==65\nassert all(o['operation']=='insert' and o['variable']=='outTemp' and o['new_value']==o['source_value'] and o['expected_old_value'] is None for o in ops)\nassert all('RESTORED' in o['reason'] and 'MODERATE provenance' in o['reason'] for o in ops)\nassert all(m['classification']=='RESTORED' and m['confidence']=='MODERATE' and m['source_evidence']['reconstruction_change_events']==0 for m in meta)\nassert all(m['source_evidence']['archive_row_presence_by_database']=={'loucka_reconstruction':False,'pocasi-loucka.eu':False,'pocasi-loucka.eu_GW1000':False,'pocasi-loucka.eu_old':True,'old_weewx':False,'weewx_WH1080':False} for m in meta)\nassert sum(b['size'] for b in batches['batches'])==65 and max(b['size'] for b in batches['batches'])<=50\nassert [b['size'] for b in batches['batches']]==[50,15]\nassert len(pres['targets'])==65 and all(x['outTemp'] is not None for x in [m['source_evidence']['source_values'] for m in meta])\nfor x in man['files']:\n p=r/x['path']; b=p.read_bytes(); assert len(b)==x['bytes'] and hashlib.sha256(b).hexdigest()==x['sha256'],x['path']\nprint('PASS: 65 RESTORED/MODERATE inserts; exact per-target source-first evidence; batch limit; manifest; no writes.')\n''')
# manifest includes all package files except manifest itself
files=[]
for p in sorted(OUT.iterdir()):
 if p.name=='manifest.json' or not p.is_file(): continue
 b=p.read_bytes(); files.append({'path':p.name,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()})
(OUT/'manifest.json').write_text(json.dumps({'schema':'meteo-proposal-package-manifest-v1','package_id':'restored-source-only-2022-august-outtemp-v1','operation_count':65,'database_writes':0,'files':files},indent=2)+'\n')
print('built',len(ops),'ops',len(files),'manifest entries')
